Translate the following Java 8 code to GNU C++11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;

public class C {

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    static long go(long x, int len) {
        x = Math.abs(x);
        if (x % ONES[len] == 0) {
            return x / ONES[len] * len;
        }
        long low = x / ONES[len];
        long high = low + 1;
        long ret1 = low * len + go(x - low * ONES[len], len - 1);
        long ret2 = high * len + go(high * ONES[len] - x, len - 1);
        return Math.min(ret1, ret2);
    }

    static long solve(long x) {
        return go(x, 16);
    }

    public static void main(String[] args) throws IOException {
        Console console = System.console();
        if (console == null) {
            // Fallback to BufferedReader if no console
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            long x = Long.parseLong(br.readLine().trim());
            System.out.println(solve(x));
        } else {
            String line = console.readLine();
            long x = Long.parseLong(line.trim());
            System.out.println(solve(x));
        }
    }
}
